const item = $input.first().json;

let rawText = "";
if (Array.isArray(item.content?.parts)) {
  for (const part of item.content.parts) {
    if (part.text && part.text.includes("{") && part.text.includes("challan_no")) {
      rawText = part.text;
    }
  }
  if (!rawText) {
    rawText = item.content.parts[item.content.parts.length - 1]?.text || "";
  }
} else {
  rawText = item.text || item.output || "{}";
}

const firstBrace = rawText.indexOf("{");
const lastBrace = rawText.lastIndexOf("}");
if (firstBrace === -1 || lastBrace === -1) {
  throw new Error("Gemini did not return valid JSON.");
}

const parsed = JSON.parse(rawText.substring(firstBrace, lastBrace + 1));

const bnToEnDigits = (str) => {
  if (!str) return "";
  const map = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};
  return String(str).replace(/[০-৯]/g, d => map[d]);
};

const cleanNum = (val) => {
  const s = bnToEnDigits(val).replace(/[^0-9.]/g, "");
  return s ? Number(s).toFixed(2) : "0.00";
};

function parseBanglaWords(words) {
  if (!words) return null;
  const w = words.replace(/,/g, " ").trim();
  const numMap = {
    'এক':1, 'দুই':2, 'তিন':3, 'চার':4, 'পাঁচ':5, 'পাচ':5, 'ছয়':6, 'ছয়':6, 'সাত':7, 'আট':8, 'নয়':9, 'নয়':9, 'দশ':10,
    'এগারো':11, 'এগার':11, 'বারো':12, 'বার':12, 'তেরো':13, 'চৌদ্দ':14, 'পনেরো':15, 'ষোল':16, 'সতেরো':17, 'আঠারো':18, 'উনিশ':19, 'বিশ':20,
    'একুশ':21, 'বাইশ':22, 'বাটন':22, 'বাইন':22, 'তেইশ':23, 'চব্বিশ':24, 'পঁচিশ':25, 'ছাব্বিশ':26, 'সাতাশ':27, 'আটাশ':28, 'ঊনত্রিশ':29, 'ত্রিশ':30,
    'একত্রিশ':31, 'বত্রিশ':32, 'তেত্রিশ':33, 'চৌত্রিশ':34, 'পঁয়ত্রিশ':35, 'ছত্রিশ':36, 'সাতত্রিশ':37, 'আটত্রিশ':38, 'ঊনচল্লিশ':39, 'চল্লিশ':40,
    'পঁয়তাল্লিশ':45, 'পঞ্চাশ':50, 'ষাট':60, 'সত্তর':70, 'আশি':80, 'নব্বই':90, 'নরাই':90, 'নঝাই':90
  };
  let total = 0, current = 0, paisa = 0, inPaisa = false;
  const tokens = w.split(/\s+/);
  for (const t of tokens) {
    if (t.includes('টাকা') || t.includes('ঢাকা')) {
      total += current; current = 0; inPaisa = true; continue;
    }
    if (t.includes('পয়সা') || t.includes('পয়সা')) {
      paisa += current; current = 0; continue;
    }
    const digitVal = Number(bnToEnDigits(t).replace(/[^0-9]/g, ""));
    if (numMap[t] !== undefined) current += numMap[t];
    else if (!isNaN(digitVal) && digitVal > 0) current += digitVal;
    else if (t.includes('কোটি')) { total += (current || 1) * 10000000; current = 0; }
    else if (t.includes('লক্ষ') || t.includes('লাখ')) { total += (current || 1) * 100000; current = 0; }
    else if (t.includes('হাজার') || t.includes('হান্ডার')) { total += (current || 1) * 1000; current = 0; }
    else if (t.includes('শত') || t.includes('শো')) { total += (current || 1) * 100; current = 0; }
  }
  if (!inPaisa) total += current; else paisa += current;
  return total > 0 ? (total + paisa / 100).toFixed(2) : null;
}

let fileName = "uploaded_challan.pdf";
try {
  fileName = $('Upload file').first().json.name || fileName;
} catch (err) {}

let challanNo = bnToEnDigits(parsed.challan_no).trim();
if (/^\d{4}-\d{10}$/.test(challanNo)) {
  challanNo = challanNo + "1";
}

const dateStr = bnToEnDigits(parsed.date).replace(/-/g, "/").trim();
let challanTotal = cleanNum(parsed.challan_total);
const deductionTaxTotal = cleanNum(parsed.deduction_tax_total);

const wordCalculated = parseBanglaWords(parsed.page1_amount_in_words_bn);
if (wordCalculated && Number(wordCalculated) > 0) {
  if (challanTotal === deductionTaxTotal || Math.abs(Number(challanTotal) - Number(wordCalculated)) > 1) {
    challanTotal = wordCalculated;
  }
}

const cleanRow = {
  file_name: fileName,
  challan_no: challanNo,
  date: dateStr,
  challan_total: `'${challanTotal}`,
  deduction_tax_total: `'${deductionTaxTotal}`,
  paid_by_name: parsed.paid_by_name ?? "",
  on_behalf_of_name: parsed.on_behalf_of_name ?? "",
  bank_and_branch: parsed.bank_and_branch ?? "",
  rag_document: `File Name: ${fileName}\nChallan Number: ${challanNo}\nDate: ${dateStr}\nChallan Total Amount: ${challanTotal} BDT (${parsed.page1_amount_in_words_bn ?? ""})\nDeduction / AIT Tax Total: ${deductionTaxTotal} BDT\nPaid By: ${parsed.paid_by_name ?? ""}\nOn Behalf Of: ${parsed.on_behalf_of_name ?? ""}\nBank & Branch: ${parsed.bank_and_branch ?? ""}`
};

return [{ json: cleanRow }];

